// The offline data: firearm models, ammo boxes and calibers from the GunsNPrices catalog.
// src/data/catalog.json is generated by scripts/build-data.mjs; the README says where the numbers come from.
import raw from "../data/catalog.json"

export type GunType = "handgun" | "rifle" | "shotgun"
export type AmmoType = "handgun" | "rifle" | "rimfire" | "shotgun"
export type CaliberType = AmmoType | "airgun" | "muzzleloader"

export const SITE = "https://gunsnprices.com"

export interface Gun {
    kind: "gun"
    /** stable item ID, e.g. "g-glock-19-gen-5" */
    id: string
    brand: string
    model: string
    type: GunType
    /** standard caliber name, e.g. "9×19mm Parabellum" */
    caliber: string
    /** product title, e.g. 'Glock 19 Gen 5 9mm 4.02" 15rd Pistol' */
    title: string
    /** typical magazine capacity */
    capacity: number
    /** typical barrel length, inches */
    barrel: number
    /** lowest in-stock price, USD */
    priceMin: number | null
    /** median in-stock price, USD */
    priceMedian: number
    /** GunsNPrices price page of the model (or its family, or brand guide), as a path */
    url: string
}

export interface Ammo {
    kind: "ammo"
    id: string
    /** store title, e.g. "Federal 9mm 124gr HST Ammunition 20rds" */
    title: string
    brand: string
    caliber: string
    caliberType: AmmoType
    rounds: number
    /** in-stock box price, USD */
    price: number
}

export type Product = Gun | Ammo

export interface Caliber {
    /** stable ID from the calibers dataset, e.g. "9x19mmparabellum" */
    id: string
    name: string
    type: CaliberType
    /** spellings retailers use */
    aliases: string[]
    /** gun and ammo listings on GunsNPrices */
    listings: number
    /** GunsNPrices ammo price page, as a path; "" when there is none */
    url: string
}

interface Table {
    fields: string[]
    rows: unknown[][]
}
interface RawCatalog {
    version: number
    snapshot: string
    attribution: string
    guns: Table
    ammo: Table
    calibers: Table
}

const data = raw as unknown as RawCatalog

function objects<T>(table: Table, extra: object): T[] {
    return table.rows.map(row => {
        const o: Record<string, unknown> = { ...extra }
        table.fields.forEach((field, i) => (o[field] = row[i]))
        return o as T
    })
}

/** day the prices were taken, e.g. "2026-10-12" */
export const SNAPSHOT: string = data.snapshot
export const ATTRIBUTION: string = data.attribution
/** firearm models, most listed first */
export const GUNS: readonly Gun[] = objects<Gun>(data.guns, { kind: "gun" })
/** ammo boxes, grouped by caliber, most listed caliber first */
export const AMMO: readonly Ammo[] = objects<Ammo>(data.ammo, { kind: "ammo" })
/** all calibers of the dataset, most listed first */
export const CALIBERS: readonly Caliber[] = objects<Caliber>(data.calibers, {})

const caliberByName = new Map(CALIBERS.map(c => [c.name, c]))

export function caliberNamed(name: string): Caliber | undefined {
    return caliberByName.get(name)
}

/** full URL for a stored path, or null */
export function siteUrl(path: string | undefined): string | null {
    return path ? SITE + path : null
}
